args.command:
$files = Get-ChildItem -Path . -Filter *.go -File -Recurse -Force -ErrorAction SilentlyContinue
$count = 0; $lines = 0
foreach ($f in $files) {
  $count++
  $bytes = [System.IO.File]::ReadAllBytes($f.FullName)
  if ($bytes.Length -eq 0) { continue }
  $n = 0
  foreach ($b in $bytes) { if ($b -eq 10) { $n++ } }
  if ($bytes[$bytes.Length-1] -ne 10) { $n++ }
  $lines += $n
}
[pscustomobject]@{files=$count; lines=$lines} | ConvertTo-Json -Compress
